"#!/bin/bash\n# Build script for sounio-pkg\n\nset -e\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Configuration\nVERSION=\"0.1.0\"\nTARGET_DIR=\"target\"\nBINARY_NAME=\"sounio-pkg\"\nSOURCE_DIR=\".\"\n\nprint_header() {\n    echo -e \"\\n${BLUE}========================================${NC}\"\n    echo -e \"${BLUE}  $1${NC}\"\n    echo -e \"${BLUE}========================================${NC}\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}✅ $1${NC}\"\n}\n\nprint_error() {\n    echo -e \"${RED}❌ $1${NC}\"\n}\n\nprint_info() {\n    echo -e \"${BLUE}ℹ️  $1${NC}\"\n}\n\n# Check prerequisites\ncheck_prerequisites() {\n    print_header \"Checking Prerequisites\"\n    \n    # Check if souc is installed\n    if ! command -v souc &> /dev/null; then\n        print_error \"Sounio compiler (souc) not found\"\n        echo \"Please install Sounio compiler first\"\n        echo \"Visit: https://sounio.dev/install\"\n        exit 1\n    fi\n    \n    print_success \"Found Sounio compiler: $(souc --version 2>/dev/null || echo 'unknown version')\"\n    \n    # Check for required tools\n    local missing_tools=()\n    for tool in git make; do\n        if ! command -v $tool &> /dev/null; then\n            missing_tools+=($tool)\n        fi\n    done\n    \n    if [ ${#missing_tools[@]} -gt 0 ]; then\n        print_error \"Missing tools: ${missing_tools[*]}\"\n        echo \"Please install missing tools and try again\"\n        exit 1\n    fi\n    \n    print_success \"All prerequisites satisfied\"\n}\n\n# Clean build artifacts\nclean() {\n    print_header \"Cleaning Build Artifacts\"\n    \n    if [ -d \"$TARGET_DIR\" ]; then\n        rm -rf \"$TARGET_DIR\"\n        print_success \"Removed target directory\"\n    else\n        print_info \"No target directory to clean\"\n    fi\n    \n    # Clean any temporary files\n    find . -name \"*.sobc\" -delete 2>/dev/null || true\n    find . -name \"*.elf\" -delete 2>/dev/null || true\n    \n    print_success \"Clean completed\"\n}\n\n# Build the package manager\nbuild() {\n    local mode=\"${1:-debug}\"\n    local target=\"${2:-native}\"\n    \n    print_header \"Building sounio-pkg ($mode mode)\"\n    \n    # Create target directory\n    mkdir -p \"$TARGET_DIR/$target\"\n    \n    # Determine optimization level\n    local optimization=\"balanced\"\n    if [ \"$mode\" = \"release\" ]; then\n        optimization=\"performance\"\n    fi\n    \n    print_info \"Mode: $mode\"\n    print_info \"Target: $target\"\n    print_info \"Optimization: $optimization\"\n    \n    # Build the CLI\n    echo \"Building CLI...\"\n    \n    # In a real implementation, this would call souc compiler\n    # souc build --bin sounio-pkg --target $target --optimization $optimization\n    \n    # For now, create a placeholder script\n    create_placeholder_binary \"$TARGET_DIR/$target/$BINARY_NAME\"\n    \n    # Make it executable\n    chmod +x \"$TARGET_DIR/$target/$BINARY_NAME\"\n    \n    print_success \"Build completed: $TARGET_DIR/$target/$BINARY_NAME\"\n}\n\n# Create a placeholder binary (for development)\ncreate_placeholder_binary() {\n    local output_path=\"$1\"\n    \n    cat > \"$output_path\" << 'EOF'\n#!/bin/bash\n# Placeholder sounio-pkg binary\n# Real implementation would be compiled Sounio code\n\necho \"📦 sounio-pkg - Package Manager for Sounio\"\necho \"   Version: 0.1.0 (development build)\"\necho \"\"\n\nif [ $# -eq 0 ]; then\n    echo \"Usage: sounio-pkg <command> [options]\"\n    echo \"\"\n    echo \"Commands:\"\n    echo \"  new <name>        Create a new package\"\n    echo \"  init              Initialize package in current directory\"\n    echo \"  build             Build the package\"\n    echo \"  test              Run tests\"\n    echo \"  add <pkg>         Add a dependency\"\n    echo \"  remove <pkg>      Remove a dependency\"\n    echo \"  list              List dependencies\"\n    echo \"  version           Show version\"\n    echo \"  help <command>    Show help for a command\"\n    echo \"\"\n    echo \"This is a development build. Real implementation coming soon!\"\n    exit 0\nfi\n\nCOMMAND=\"$1\"\nshift\n\ncase \"$COMMAND\" in\n    \"new\")\n        if [ -z \"$1\" ]; then\n            echo \"Error: Package name required\"\n            echo \"Usage: sounio-pkg new <name>\"\n            exit 1\n        fi\n        echo \"📦 Creating new package: $1\"\n        echo \"   (Placeholder - would create package structure)\"\n        ;;\n    \"version\")\n        echo \"sounio-pkg 0.1.0 (development)\"\n        ;;\n    \"help\")\n        echo \"Help for sounio-pkg\"\n        ;;\n    *)\n        echo \"Command '$COMMAND' recognized but not implemented yet\"\n        echo \"This is a development build\"\n        ;;\nesac\nEOF\n}\n\n# Run tests\ntest() {\n    print_header \"Running Tests\"\n    \n    # Unit tests\n    echo \"Running unit tests...\"\n    # souc test\n    \n    # Integration tests\n    echo \"Running integration tests...\"\n    # ./scripts/test-integration.sh\n    \n    print_success \"Tests completed (placeholder)\"\n}\n\n# Package for distribution\npackage() {\n    local mode=\"${1:-release}\"\n    \n    print_header \"Packaging sounio-pkg\"\n    \n    # Build first\n    build \"$mode\" \"native\"\n    \n    # Create package directory\n    local package_dir=\"$TARGET_DIR/dist/sounio-pkg-$VERSION\"\n    mkdir -p \"$package_dir\"\n    \n    # Copy files\n    cp -r \"$TARGET_DIR/native/$BINARY_NAME\" \"$package_dir/\"\n    cp README.md \"$package_dir/\"\n    cp LICENSE \"$package_dir/\"\n    cp -r examples \"$package_dir/\" 2>/dev/null || true\n    \n    # Create install script\n    cat > \"$package_dir/install.sh\" << 'EOF'\n#!/bin/bash\n# Installation script for sounio-pkg\n\nset -e\n\nBINARY=\"sounio-pkg\"\nINSTALL_DIR=\"/usr/local/bin\"\n\nif [ \"$(id -u)\" -ne 0 ]; then\n    echo \"This script requires root privileges. Please run with sudo.\"\n    exit 1\nfi\n\necho \"Installing sounio-pkg...\"\ncp \"$BINARY\" \"$INSTALL_DIR/\"\nchmod +x \"$INSTALL_DIR/$BINARY\"\n\necho \"Installation complete!\"\necho \"Run 'sounio-pkg --version' to verify.\"\nEOF\n    \n    chmod +x \"$package_dir/install.sh\"\n    \n    # Create tarball\n    cd \"$TARGET_DIR/dist\"\n    tar -czf \"sounio-pkg-$VERSION-$mode.tar.gz\" \"sounio-pkg-$VERSION\"\n    cd - > /dev/null\n    \n    print_success \"Package created: $TARGET_DIR/dist/sounio-pkg-$VERSION-$mode.tar.gz\"\n}\n\n# Install locally\ninstall_local() {\n    local mode=\"${1:-debug}\"\n    \n    print_header \"Installing sounio-pkg locally\"\n    \n    # Build if needed\n    if [ ! -f \"$TARGET_DIR/native/$BINARY_NAME\" ]; then\n        build \"$mode\" \"native\"\n    fi\n    \n    # Install to ~/.local/bin\n    local install_dir=\"$HOME/.local/bin\"\n    mkdir -p \"$install_dir\"\n    \n    cp \"$TARGET_DIR/native/$BINARY_NAME\" \"$install_dir/\"\n    \n    # Update PATH if not already\n    if [[ \":$PATH:\" != *\":$install_dir:\"* ]]; then\n        echo \"export PATH=\\\"$install_dir:\\\$PATH\\\"\" >> \"$HOME/.bashrc\"\n        echo \"Added $install_dir to PATH in .bashrc\"\n    fi\n    \n    print_success \"Installed to: $install_dir/$BINARY_NAME\"\n    echo \"You may need to restart your shell or run: source ~/.bashrc\"\n}\n\n# Show usage\nusage() {\n    echo \"Usage: $0 [command]\"\n    echo \"\"\n    echo \"Commands:\"\n    echo \"  check           Check prerequisites\"\n    echo \"  clean           Clean build artifacts\"\n    echo \"  build [mode]    Build (debug|release, default: debug)\"\n    echo \"  test            Run tests\"\n    echo \"  package [mode]  Create distribution package\"\n    echo \"  install [mode]  Install locally\"\n    echo \"  all             Clean, build, test, and package\"\n    echo \"\"\n    echo \"Examples:\"\n    echo \"  $0 check\"\n    echo \"  $0 build release\"\n    echo \"  $0 install\"\n}\n\n# Main execution\nmain() {\n    local command=\"${1:-all}\"\n    \n    case \"$command\" in\n        \"check\")\n            check_prerequisites\n            ;;\n        \"clean\")\n            clean\n            ;;\n        \"build\")\n            build \"${2:-debug}\"\n            ;;\n        \"test\")\n            test\n            ;;\n        \"package\")\n            package \"${2:-release}\"\n            ;;\n        \"install\")\n            install_local \"${2:-debug}\"\n            ;;\n        \"all\")\n            check_prerequisites\n            clean\n            build \"release\"\n            test\n            package \"release\"\n            ;;\n        \"--help\" | \"-h\")\n            usage\n            ;;\n        *)\n            print_error \"Unknown command: $command\"\n            usage\n            exit 1\n            ;;\n    esac\n}\n\n# Run main function\nmain \"$@\""